SCENES.s1 = { id: 's1', title: 'the anatomy of a test', app: 'todo', intro: 'Five lines are enough for a real test. Watch them appear, and read what each one does.', steps: [
  { py: 'page.goto("https://demo.playwright.dev/todomvc/")', kt: 'page.navigate("https://demo.playwright.dev/todomvc/")', say: 'Every test starts by opening a page. In this lab the page is already open, so this line only reloads it. On your own computer it is the line that makes the browser go to the address.' },
  { py: 'new_todo = page.get_by_placeholder("What needs to be done?")', kt: 'val newTodo = page.getByPlaceholder("What needs to be done?")', say: 'Find the input the way a person would: by the grey hint text inside it. This line only <b>describes</b> where to look. Look at the log: nothing was searched yet.' },
  { py: 'new_todo.fill("Buy milk")', kt: 'newTodo.fill("Buy milk")', say: '<b>Act.</b> Now Playwright looks for the input, waits until it is ready, and types the text. If the input is not there yet, it waits instead of failing at once.' },
  { py: 'new_todo.press("Enter")', kt: 'newTodo.press("Enter")', say: 'Press Enter, exactly as a user would to add the item. The new todo appears in the list.' },
  { py: 'expect(page.get_by_test_id("todo-title")).to_have_text("Buy milk")', kt: 'assertThat(page.getByTestId("todo-title")).hasText("Buy milk")', say: '<b>Check.</b> A test without a check proves nothing. This assertion retries until the text is "Buy milk" or a few seconds pass, so it copes with a page that is a little slow.' }
] };

LABS.l2a = { id: 'l2a', title: 'your first test', app: 'todo',
  goal: 'Add one todo called <b>Buy milk</b> and check that it appears in the list. Find the input by its placeholder text, press Enter to add the todo, and finish with an assertion.',
  starter: { py: '# 1. Find the input by its placeholder and type a todo\n# 2. Press Enter to add it\n# 3. Check that the list shows "Buy milk"\n', kt: '// 1. Find the input by its placeholder and type a todo\n// 2. Press Enter to add it\n// 3. Check that the list shows "Buy milk"\n' },
  hints: ['The input shows the hint text "What needs to be done?". The locator for that is <code>get_by_placeholder</code> in Python and <code>getByPlaceholder</code> in Kotlin.', 'To add the todo, press the Enter key inside the same input: <code>press("Enter")</code>.', 'Finish with a web-first assertion: <code>expect(locator).to_have_text(...)</code> in Python, <code>assertThat(locator).hasText(...)</code> in Kotlin. The title of a todo has the test id <code>todo-title</code>.'],
  solution: { py: 'new_todo = page.get_by_placeholder("What needs to be done?")\nnew_todo.fill("Buy milk")\nnew_todo.press("Enter")\nexpect(page.get_by_test_id("todo-title")).to_have_text("Buy milk")', kt: 'val newTodo = page.getByPlaceholder("What needs to be done?")\nnewTodo.fill("Buy milk")\nnewTodo.press("Enter")\nassertThat(page.getByTestId("todo-title")).hasText("Buy milk")' },
  checks: [
    { t: 'Types "Buy milk" into the input', k: 'did', action: 'fill', key: 'new-todo', value: 'Buy milk' },
    { t: 'Presses Enter in the input', k: 'did', action: 'press', key: 'new-todo', value: 'Enter' },
    { t: 'Ends with a web-first text assertion', k: 'asserted', type: 'toHaveText' },
    { t: 'The list has exactly one todo', k: 'finalCount', key: 'item', count: 1 }
  ] };

SCENES.s3 = { id: 's3', title: 'finding the Sign in button', app: 'login', intro: 'A first idea does not always work. Watch the error appear, read it, and fix it.', steps: [
  { full: true, py: 'page.get_by_text("Sign in").click()', kt: 'page.getByText("Sign in").click()', say: 'First try: find the button by its text. Look at the error. The words "Sign in" appear twice on this page: in the heading and on the button. Playwright refuses to guess which one you mean. This is <b>strict mode</b>, and it protects you from clicking the wrong thing.' },
  { full: true, py: 'page.get_by_role("button", name="Sign in").click()', kt: 'page.getByRole(AriaRole.BUTTON, Page.GetByRoleOptions().setName("Sign in")).click()', say: 'Better: say what <b>kind</b> of thing it is (a button) and what it is called. Now only one element fits. The click works, and the page answers that the email is missing.' },
  { py: 'expect(page.get_by_role("alert")).to_have_text("Email is required")', kt: 'assertThat(page.getByRole(AriaRole.ALERT)).hasText("Email is required")', say: 'Check the message. An error message has the role "alert", so we can find it without any CSS.' },
  { full: true, py: 'page.get_by_label("Email").fill("ada@example.com")\npage.get_by_label("Password").fill("secret123")\npage.get_by_role("button", name="Sign in").click()\nexpect(page.get_by_role("heading", name="Welcome, Ada")).to_be_visible()', kt: 'page.getByLabel("Email").fill("ada@example.com")\npage.getByLabel("Password").fill("secret123")\npage.getByRole(AriaRole.BUTTON, Page.GetByRoleOptions().setName("Sign in")).click()\nassertThat(page.getByRole(AriaRole.HEADING, Page.GetByRoleOptions().setName("Welcome, Ada"))).isVisible()', say: 'The whole flow. Fields are found by their <b>label</b>, the button by <b>role and name</b>, the result by the heading. Every locator reads like a sentence about what the user sees.' }
] };

