SCENES.s4 = { id: 's4', title: 'why not just sleep?', app: 'slow', intro: 'This page needs a moment to load a report, and its Download button is disabled for a while. Watch how Playwright copes without a single sleep.', steps: [
  { py: 'page.get_by_role("button", name="Load report").click()', kt: 'page.getByRole(AriaRole.BUTTON, Page.GetByRoleOptions().setName("Load report")).click()', say: 'Click the button. The page now takes 1.5 seconds to produce the report. A manual tester would simply wait and look.' },
  { py: 'expect(page.get_by_text("Report ready")).to_be_visible()', kt: 'assertThat(page.getByText("Report ready")).isVisible()', say: 'No sleep. The assertion keeps checking until the text appears. Look at the log: it passed after waiting <b>1500 ms</b>, which is the time the page really needed (the lab uses a virtual clock, so this is instant for you).' },
  { py: 'page.get_by_role("button", name="Download CSV").click()', kt: 'page.getByRole(AriaRole.BUTTON, Page.GetByRoleOptions().setName("Download CSV")).click()', say: 'The Download button is still disabled for another half second. A click does not fail: it waits until the button is enabled, and then clicks. This is <b>auto-waiting</b>.' },
  { py: 'expect(page.get_by_text("File saved")).to_be_visible()', kt: 'assertThat(page.getByText("File saved")).isVisible()', say: 'Check the result. The whole test has no fixed delay, so it is as fast as the page allows and still works if the page is slower tomorrow.' }
] };

